WITH sm_ok AS (
  SELECT DISTINCT id FROM laboratory WHERE "sm" IN ('negative','0')
),
no_thr AS (
  SELECT id FROM sm_ok s WHERE NOT EXISTS (SELECT 1 FROM examination e WHERE e.id = s.id AND e.thrombosis > 0)
),
prot AS (
  SELECT DISTINCT id FROM laboratory
  WHERE "U-PRO" IN ('30','100','300','+1(30)','+2(100)','>=300','>=1000')
)
SELECT count(*) AS patients
FROM no_thr n
JOIN prot p ON p.id = n.id;
